@page{margin:0;size:9.2cm 12.4cm}*{box-sizing:border-box}body{margin:0;font-family:DejaVu Sans,sans-serif}.card{position:relative;width:9.2cm;height:12.4cm;overflow:hidden;background:{{$setting->primary_color}};color:{{$setting->text_color}}}.bg{position:absolute;inset:0;opacity:{{$setting->background_opacity/100}};background-position:center;background-size:cover}.overlay{position:absolute;inset:0;background:{{$setting->primary_color}};opacity:.72}.accent{position:absolute;right:-1.7cm;top:-1.5cm;width:4cm;height:4cm;border-radius:50%;background:{{$setting->accent_color}}}.content{position:absolute;inset:.58cm .62cm .48cm;text-align:center}.header{height:3.25cm;text-align:center}.logo{width:4cm;height:2cm;margin:0 auto;text-align:center}.logo img{max-width:4cm;max-height:2cm}.heading{padding-top:.14cm}.heading span{font-size:5.5pt;font-weight:bold;letter-spacing:1.3px}.heading strong{display:block;margin:.08cm auto 0;max-width:7.5cm;font-size:8.4pt;line-height:1.15;text-transform:uppercase}.main{height:7.1cm;padding-top:.18cm;text-align:center}.photo{width:2.75cm;height:3.67cm;margin:0 auto .28cm;border:.09cm solid #fff;border-radius:.13cm;background:#e8ebef;overflow:hidden}.photo img{width:100%;height:100%;object-fit:cover}.identity{text-align:center}.identity small{font-size:5.2pt;font-weight:bold;letter-spacing:1.5px}.identity h1{margin:.1cm auto .13cm;max-width:7.4cm;font-size:14.5pt;line-height:1.08;text-transform:uppercase}.line{width:1.05cm;height:.07cm;margin:0 auto .16cm;background:{{$setting->accent_color}}}.identity p{margin:.04cm 0;font-size:6.8pt}.footer{position:absolute;left:0;right:0;bottom:0;padding-top:.18cm;border-top:.02cm solid rgba(255,255,255,.4);font-size:5.4pt;text-align:left}.footer .right{float:right;max-width:4cm;text-align:right}
